/**
 * @file RecommendationFeed.jsx
 * @description AI-recommended prioritized action items generated by LangGraph reasoning.
 * @author Sargam Banerjee (Member 4)
 */

import React from 'react';
import { Zap, AlertTriangle, ArrowRight, BookOpen, MessageSquare, FolderPlus } from 'lucide-react';

export default function RecommendationFeed({ recommendations = [] }) {
  const iconByCategory = {
    skill: <Zap className="w-4 h-4 text-indigo-600" />,
    interview: <MessageSquare className="w-4 h-4 text-emerald-600" />,
    evidence: <FolderPlus className="w-4 h-4 text-blue-600" />
  };

  const badgeByPriority = {
    high: 'bg-red-50 text-red-700 border border-red-200',
    medium: 'bg-amber-50 text-amber-700 border border-amber-200',
    low: 'bg-blue-50 text-blue-700 border border-blue-200'
  };

  return (
    <div className="space-y-3">
      {recommendations.map((rec) => (
        <div
          key={rec.id}
          className="p-3.5 rounded-xl border border-slate-200 bg-white hover:border-indigo-200 transition-all flex items-start justify-between gap-3 shadow-xs"
        >
          <div className="flex items-start space-x-3">
            <div className="p-2 rounded-lg bg-slate-50 border border-slate-100 flex-shrink-0 mt-0.5">
              {iconByCategory[rec.category] || <Zap className="w-4 h-4 text-indigo-600" />}
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <span className="text-sm font-semibold text-slate-800">{rec.title}</span>
                <span
                  className={`text-[10px] font-bold uppercase px-1.5 py-0.5 rounded ${badgeByPriority[rec.priority]}`}
                >
                  {rec.priority}
                </span>
              </div>
              <p className="text-xs text-slate-500 mt-1 leading-relaxed">
                {rec.description}
              </p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
